"""Dale Carnegie Strategy Module ("How to Win Friends and Influence People").

Core Tenets applied to B2B Industrial Negotiations:
1. Sincere Appreciation: Acknowledge the supplier's technical capability, quality, and partnership.
2. Focus on the Counterpart's Interests: Appeal to what the supplier values (liquidity, capacity planning, contract certainty).
3. Collaborative Problem Solving: Frame price discussions as mutual market adjustments rather than disputes.
4. Respectful Phrasing: Never aggressively claim the supplier is wrong; present shared facts and invite their partnership.
"""

from dataclasses import dataclass
from typing import List, Optional


@dataclass
class CarnegieTactics:
    appreciation: str
    interest_alignment: str
    collaborative_hook: str


class CarnegieStrategy:
    """Provides Dale Carnegie conversational framing and heuristics."""

    @staticmethod
    def get_tactics(category_goal: str, round_num: int, supplier_name: Optional[str] = None) -> CarnegieTactics:
        name = supplier_name or "Partner"
        if round_num <= 1:
            appreciation = (
                f"We value our business relationship with {name} and greatly respect your manufacturing excellence."
            )
            interest_alignment = (
                "Our goal is to secure a dependable, long-term agreement that guarantees consistent plant utilization for your operations."
            )
            collaborative_hook = (
                "How can we align our mutual cost structures so this remains a profitable and stable engagement for both of us?"
            )
        elif round_num <= 3:
            appreciation = (
                "Thank you for your constructive engagement and for sharing your quote details."
            )
            if category_goal in ("stabilise", "secure_supply"):
                interest_alignment = (
                    "We want to ensure your operations maintain sustainable margins while keeping our procurement competitive."
                )
            else:
                interest_alignment = (
                    "To support your working capital and liquidity, we are open to tailoring our payment terms."
                )
            collaborative_hook = (
                "We want to find a solution where our volume commitments directly support your planning security."
            )
        else:
            appreciation = (
                "We appreciate the efforts made so far to bridge our expectations."
            )
            interest_alignment = (
                "We are prepared to finalize a binding agreement today that provides immediate commercial certainty."
            )
