"""Chris Voss Strategy Module ("Never Split the Difference").

Core Techniques applied to B2B Industrial Negotiations:
1. Tactical Empathy: Recognize and validate the supplier's commercial reality and challenges.
2. Labeling: Explicitly name their pain points.
3. Accusation Audit: Preemptively neutralize their defensiveness.
4. Calibrated Questions: Open-ended "How" and "What" questions.
5. "No"-Oriented Framing: Frame proposals so agreement gives them psychological control.
6. Strategic Anchoring: Counter their opening price with a firm, data-backed anchor.
"""

from dataclasses import dataclass


@dataclass
class VossTactics:
    label: str
    calibrated_question: str
    accusation_audit: str | None = None


class VossStrategy:
    """Provides Chris Voss tactical empathy, labeling, and calibrated questioning."""

    @staticmethod
    def get_tactics(category_goal: str, round_num: int, context_type: str = "price_increase") -> VossTactics:
        if context_type == "price_increase":
            if round_num <= 1:
                label = (
                    "It seems like rising input costs and market volatility have created significant "
                    "pressure on your operations."
                )
                calibrated_question = (
                    "How are you seeing these energy and material index shifts play out across production?"
                )
                accusation_audit = (
                    "You probably feel we are being overly demanding regarding our baseline expectations."
                )
            elif round_num <= 3:
                label = (
                    "It appears that securing stable cash flow and reliable volume commitments is critical "
                    "for your planning right now."
                )
                calibrated_question = (
                    "How can we structure this contract so it addresses your working capital needs without "
                    "exceeding our market cost ceiling?"
                )
                accusation_audit = None
            else:
                label = "It sounds like we are very close to an arrangement that works for both organizations."
                calibrated_question = "What would it take to finalize agreement on these terms today?"
                accusation_audit = None
        elif context_type == "quality":
            label = (
                "It seems that maintaining stringent PPM thresholds while scaling output requires dedicated "
                "quality alignment."
            )
            calibrated_question = (
                "How can we jointly structure chargebacks and 8D report timelines to eliminate root causes?"
            )
            accusation_audit = None
        elif context_type == "rfq":
            label = (
                "It seems like competing against rival suppliers on lead times and unit pricing requires "
                "clear transparency."
            )
            calibrated_question = (
                "What flexibility do you have on volume commitments if we consolidate our demand with you?"
            )
            accusation_audit = None
        else:  # renewal / general
            label = "It seems like predictable long-term capacity utilization is the top priority for your management."
            calibrated_question = (
                "How can we optimize our contract duration to provide that certainty while reflecting market indices?"
            )
            accusation_audit = None

        return VossTactics(
            label=label,
            calibrated_question=calibrated_question,
            accusation_audit=accusation_audit,
        )

    @staticmethod
    def system_prompt_rules() -> str:
        return (
            "- CHRIS VOSS TECHNIQUES: (Tactical Empathy) Use labeling ('It seems like...', 'It sounds like...') "
            "to demonstrate that you understand their commercial pressures. "
            "(Calibrated Questions) Ask open-ended 'How' or 'What' questions rather than blunt demands."
        )

"""Dale Carnegie Strategy Module ("How to Win Friends and Influence People").

Core Tenets applied to B2B Industrial Negotiations:
1. Sincere Appreciation: Acknowledge the supplier's technical capability, quality, and partnership.
2. Focus on Counterpart Interests: Appeal to liquidity, capacity planning, and contract certainty.
3. Collaborative Problem Solving: Frame price discussions as mutual market adjustments.
4. Respectful Phrasing: Never aggressively claim the supplier is wrong.
"""

from dataclasses import dataclass


@dataclass
class CarnegieTactics:
    appreciation: str
    interest_alignment: str
    collaborative_hook: str


class CarnegieStrategy:
    """Provides Dale Carnegie conversational framing and heuristics."""

    @staticmethod
    def get_tactics(category_goal: str, round_num: int, supplier_name: str | None = None) -> CarnegieTactics:
        name = supplier_name or "Partner"
        if round_num <= 1:
            appreciation = (
                f"We value our business relationship with {name} and greatly respect your manufacturing excellence."
            )
            interest_alignment = (
                "Our goal is to secure a dependable agreement that guarantees consistent plant utilization."
            )
            collaborative_hook = (
                "How can we align our mutual cost structures so this remains a profitable engagement for both of us?"
            )
        elif round_num <= 3:
            appreciation = "Thank you for your constructive engagement and for sharing your quote details."
            if category_goal in ("stabilise", "secure_supply"):
                interest_alignment = (
                    "We want to ensure your operations maintain sustainable margins while keeping us competitive."
                )
            else:
                interest_alignment = (
                    "To support your working capital and liquidity, we are open to tailoring our payment terms."
                )
            collaborative_hook = (
                "We want to find a solution where our volume commitments directly support your planning security."
            )
        else:
            appreciation = "We appreciate the efforts made so far to bridge our expectations."
            interest_alignment = (
                "We are prepared to finalize a binding agreement today that provides immediate commercial certainty."
            )
            collaborative_hook = "Let us settle on a package that allows us to move forward together successfully."

        return CarnegieTactics(
            appreciation=appreciation,
            interest_alignment=interest_alignment,
            collaborative_hook=collaborative_hook,
        )

    @staticmethod
    def system_prompt_rules() -> str:
        return (
            "- CARNEGIE PRINCIPLE: Maintain professional warmth and sincere respect. "
            "Acknowledge the supplier's manufacturing craft and appeal to their self-interest "
            "(steady volume, cash flow, planning stability). Never insult or accuse."
        )

"""Robert Greene's "48 Laws of Power" adapted for B2B Procurement Negotiations.

Selected Laws Applied:
- Law 3: Conceal Your Intentions
  Never reveal urgency, internal cost thresholds, or an absence of alternatives.
- Law 4: Always Say Less Than Necessary
  Keep messages crisp, precise, and devoid of unnecessary verbiage (<= 120 words).
- Law 9: Win Through Actions, Never Through Argument
  Only term sheets bind. Cite verified data facts and propose concrete terms.
- Law 13: Appeal to Self-Interest, Never to Mercy
  Show how faster payment or long-term commitment serves the supplier.
- Law 16: Use Absence to Create Respect
  Never accept an opening offer. Concede in small, disciplined increments.
- Law 31: Control the Options (The Card Dealer's Gambit)
  Present 2 to 3 alternative term sheets where all choices benefit Hollerau.
- Law 47: In Victory, Know When to Stop
  When 'final_offer' is reached or target is met, execute closure.
"""

from dataclasses import dataclass


@dataclass
class PowerRules:
    conceal_intent: str
    brevity_directive: str
    concession_discipline: str
    closing_discipline: str


class GreeneStrategy:
    """Encapsulates strategic power dynamics and discipline rules."""

    @staticmethod
    def get_power_directives() -> PowerRules:
        return PowerRules(
            conceal_intent=(
                "Never disclose internal deadlines, production schedules, budget ceilings, or alternative gaps."
            ),
            brevity_directive=(
                "Keep messages tightly bounded under 120 words. State facts, cite data IDs, propose term sheets."
            ),
            concession_discipline=(
                "Do not concede prematurely. Make step-by-step counter-moves tied to tradeable attributes."
            ),
            closing_discipline=(
                "When status is 'agreed' or 'final_offer' and terms beat alternative, accept without pushing further."
            ),
        )

    @staticmethod
    def evaluate_closure(
        status: str,
        moves_left: int,
        c_standing: float,
        c_alt: float,
        c_target: float,
        round_num: int,
    ) -> bool:
        """Determines whether Law 47 dictates closing immediately."""
        if status == "agreed":
            return True
        if status == "final_offer":
            return c_standing <= c_alt
        if moves_left <= 1:
            return c_standing <= c_alt
        if round_num >= 3 and c_standing <= c_target:
            return True
        return False

    @staticmethod
    def system_prompt_rules() -> str:
        return (
            "- 48 LAWS OF POWER: (Law 3) Never reveal urgency, deadlines, or lack of alternatives. "
            "(Law 4) Say less than necessary (concise business tone, strictly <= 120 words). "
            "(Law 9) Never argue in prose without proposing concrete term sheets. "
            "(Law 31) Propose distinct alternative term sheets so the supplier chooses between our favorable options. "
            "(Law 47) Know when to stop: do not over-negotiate when an acceptable deal is on the table."
        )

"""Fisher & Ury Strategy Module ("Getting to Yes" / Harvard Negotiation Project).

Four Pillars of Principled Negotiation:
1. Separate People from the Problem:
   Address the commercial variables and market indices objectively.
2. Focus on Interests, Not Positions:
   Move past stated price increases (+9.5%) to underlying interests (cash flow, capacity utilization).
3. Invent Options for Mutual Gain:
   Trade non-zero-sum attributes (e.g., faster payment terms for unit price discounts).
4. Insist on Objective Criteria:
   Base all claims on verifiable public benchmarks (PPI, LCI, should-cost, historical POs).
5. Understand and Protect your BATNA:
   Never accept any deal with total cost C higher than your alternative (c_alt).
"""

import math
from dataclasses import dataclass


@dataclass
class BatnaAssessment:
    has_alternative: bool
    c_alt: float
    c_standing: float
    deal_beats_batna: bool
    advantage_eur: float


class HarvardStrategy:
    """Implements principled negotiation checks and objective criteria reasoning."""

    @staticmethod
    def assess_batna(c_standing: float, c_alt: float) -> BatnaAssessment:
        has_alt = c_alt < math.inf and c_alt > 0
        beats = c_standing <= c_alt if has_alt else True
        advantage = (c_alt - c_standing) if has_alt else 0.0
        return BatnaAssessment(
            has_alternative=has_alt,
            c_alt=c_alt,
            c_standing=c_standing,
            deal_beats_batna=beats,
            advantage_eur=advantage,
        )

    @staticmethod
    def objective_criteria_framing(verified_claims: list) -> str:
        """Constructs an objective criteria argument from verified facts."""
        if not verified_claims:
            return "Our counter-proposal reflects standard industry cost benchmarks and market index paths."

        clauses = []
        for claim in verified_claims:
            clauses.append(claim["sentence"])
        return " ".join(clauses)

    @staticmethod
    def system_prompt_rules() -> str:
        return (
            "- HARVARD PRINCIPLED NEGOTIATION: (Objective Criteria) Ground arguments in verified facts. "
            "(Separate people from problem) Be tough on the data, gentle and respectful to the person. "
            "(Invent options for mutual gain) Propose trades between price, payment speed, and volume. "
            "(Protect BATNA) Never accept a deal that costs more than our alternative."
        )

"""Fact Mining & Objective Criteria Engine.

Extracts checkable facts from the data package and case context, computing figures
within the arena's exact tolerances (+-0.5 pp for %, +-0.5% for EUR/numbers).
Respects the rule: max 3 claims per message, single sentence per claim, avoid duplicates.
"""

import logging
from typing import Any

log = logging.getLogger("arena.facts")


class FactMiner:
    """Mines verified facts from case.refs, case.facts, and DataPackage."""

    @classmethod
    def mine_claims(
        cls,
        case: dict[str, Any],
        data_service: Any,
        already_cited: set[str],
        max_claims: int = 2,
    ) -> list[dict[str, Any]]:
        """Mines up to max_claims unused, verified claims for the current message."""
        claims: list[dict[str, Any]] = []
        facts = case.get("facts", {})
        refs = case.get("refs", [])

        # 1. Search for pairs of idx: series to form index change claims
        idx_refs = [r for r in refs if r.startswith("idx:") and r not in already_cited]
        by_series: dict[str, list[tuple[str, str, float]]] = {}
        for r in idx_refs:
            val = cls._lookup_fact(r, facts, data_service)
            if val and "series" in val and "month" in val and "value" in val:
                by_series.setdefault(val["series"], []).append((r, val["month"], float(val["value"])))

        for series, points in by_series.items():
            if len(claims) >= max_claims:
                break
            if len(points) >= 2:
                points.sort(key=lambda x: x[1])
                earlier, later = points[0], points[-1]
                p0, p1 = earlier[2], later[2]
                if p0 > 0:
                    pct_change = round(((p1 / p0) - 1.0) * 100.0, 1)
                    r_early, r_late = earlier[0], later[0]
                    sentence = (
                        f"The price index {series} moved {pct_change:+.1f}% from {earlier[1]} to {later[1]} "
                        f"({r_early}, {r_late})."
                    )
                    claims.append({
                        "ids": [r_early, r_late],
                        "sentence": sentence,
                        "type": "index_change",
                        "value": pct_change,
                    })

        # 2. Search for scorecards (sc:) to form OTD or PPM claims
        sc_refs = [r for r in refs if r.startswith("sc:") and r not in already_cited]
        for r in sc_refs:
            if len(claims) >= max_claims:
                break
            val = cls._lookup_fact(r, facts, data_service)
            if val:
                otd = val.get("otd_pct")
                ppm = val.get("ppm")
                quarter = val.get("quarter", "")
                if otd is not None and float(otd) < 95.0:
                    otd_val = round(float(otd), 1)
                    sentence = f"Scorecard records ({r}) show on-time delivery at {otd_val}% in {quarter}."
                    claims.append({
                        "ids": [r],
                        "sentence": sentence,
                        "type": "otd",
                        "value": otd_val,
                    })
                elif ppm is not None and float(ppm) > 500:
                    ppm_val = int(ppm)
                    sentence = f"Quality records show a defect rate of {ppm_val} PPM ({r})."
                    claims.append({
                        "ids": [r],
                        "sentence": sentence,
                        "type": "ppm",
                        "value": ppm_val,
                    })

        # 3. Search for should-cost benchmarks (cost:)
        parts = case.get("parts", [])
        for p in parts:
            if len(claims) >= max_claims:
                break
            cost_id = f"cost:{p.split(':')[-1]}" if ":" in p else f"cost:{p}"
            if cost_id in refs and cost_id not in already_cited:
                val = cls._lookup_fact(cost_id, facts, data_service)
                if val and "unit_cost" in val:
                    unit_cost = round(float(val["unit_cost"]), 2)
                    sentence = (
                        f"Engineering bottom-up should-cost indicates a baseline of EUR {unit_cost:.2f} ({cost_id})."
                    )
                    claims.append({
                        "ids": [cost_id],
                        "sentence": sentence,
                        "type": "should_cost",
                        "value": unit_cost,
                    })

        # 4. Search for purchase order history (po:)
        po_refs = [r for r in refs if r.startswith("po:") and r not in already_cited]
        if po_refs and len(claims) < max_claims:
            p_ref = po_refs[0]
            val = cls._lookup_fact(p_ref, facts, data_service)
            if val and "unit_price" in val:
                po_price = round(float(val["unit_price"]), 2)
                sentence = f"Historical purchase orders reflect an agreed price level of EUR {po_price:.2f} ({p_ref})."
                claims.append({
                    "ids": [p_ref],
                    "sentence": sentence,
                    "type": "po",
                    "value": po_price,
                })

        return claims[:max_claims]

    @classmethod
    def _lookup_fact(cls, ref: str, case_facts: dict[str, Any], data_service: Any) -> dict[str, Any] | None:
        if ref in case_facts:
            return case_facts[ref]
        if data_service:
            try:
                res = data_service.lookup(ref)
                if res:
                    return res
            except Exception as e:
                log.debug("Data lookup error for %s: %s", ref, e)
        return None

