def make_quote_text(stated: dict[str, Any], standard: dict[str, Any] | None = None) -> str:
    lines = ["Offered terms"]
    for k, v in stated.items():
        if k in NAMES and v is not None:
            if k == "index_clause" and isinstance(v, dict):
                lines.append(f"{NAMES[k]} {v['series']}, {int(v['material_share']*100)}% material, deadband {v['deadband_pct']} %, base {v['base_month']}")
            else:
                lines.append(f"{NAMES[k]} {v}")
    if standard:
        lines.append("Our standard terms")
        for k, v in standard.items():
            if k in NAMES and v is not None:
                lines.append(f"{NAMES[k]} {v}")
    return "\n".join(lines)


