import math

def target_price(case_type, open_p, curr_p, r, r_limit=10, should_cost=None):
    if curr_p and curr_p < open_p and case_type in ("price_increase", "raw_material", "quality"):
        bottom = curr_p * 0.99 if not should_cost else max(should_cost, curr_p * 0.98)
        bottom = min(bottom, open_p * 0.97)
    elif should_cost and should_cost > 0:
